import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import api from "../api/api";

function HomePage() {
  const [books, setBooks] = useState([]);
  const [loading, setLoading] = useState(true);
  const navigate = useNavigate();

  useEffect(() => {
    fetchFeaturedBooks();
  }, []);

  const fetchFeaturedBooks = async () => {
    try {
      const response = await api.get("/books");
      setBooks(response.data.slice(0, 6));
      setLoading(false);
    } catch (error) {
      console.error("Error fetching featured books:", error);
      setLoading(false);
    }
  };

  return (
    <div>
      {/* Hero Section */}
      <section className="hero">
        <div className="hero-content">
          <h1>Stories That Spark Joy</h1>
          <p>Discover the world's most captivating books. Find your next favorite read from our curated collection.</p>
          <button className="btn-primary" onClick={() => navigate("/register")}>
            Start Reading Today
          </button>
        </div>
        <div className="hero-image">
          <img 
            src="https://images.unsplash.com/photo-1507842072343-583f20270319?w=500&h=600&fit=crop" 
            alt="Reading"
          />
        </div>
      </section>

      {/* Featured Books Section */}
      <section className="featured-section">
        <div className="container">
          <h2>Featured Bestsellers</h2>
          {loading ? (
            <p style={{ textAlign: "center" }}>Loading books...</p>
          ) : (
            <div className="book-grid">
              {books.map((book) => (
                <div key={book.id} className="book-card">
                  <div className="book-card-image">
                    <img 
                      src={book.coverImageUrl || "https://via.placeholder.com/250x350?text=No+Cover"} 
                      alt={book.title}
                    />
                  </div>
                  <div className="book-card-content">
                    <div className="book-card-title">{book.title}</div>
                    <div className="book-card-author">{book.author}</div>
                    <div className="book-card-price">${book.price}</div>
                    <button className="book-card-button">View Details</button>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      </section>

      {/* CTA Section */}
      <section className="cta-section">
        <div className="container">
          <h2>Ready to Explore More?</h2>
          <p>Browse our complete collection of thousands of books across all genres</p>
          <button className="btn-primary" onClick={() => navigate("/")}>
            Browse Catalog
          </button>
        </div>
      </section>
    </div>
  );
}

export default HomePage;
